import strawberry
from fastapi import FastAPI
from strawberry.fastapi import GraphQLRouter

@strawberry.type
class {{type_name}}:
    id: str
    name: str

_store: list[{{type_name}}] = []

@strawberry.type
class Query:
    @strawberry.field
    def items(self) -> list[{{type_name}}]:
        return _store

@strawberry.type
class Mutation:
    @strawberry.mutation
    def add(self, name: str) -> {{type_name}}:
        item = {{type_name}}(id=str(len(_store) + 1), name=name)
        _store.append(item)
        return item

schema = strawberry.Schema(query=Query, mutation=Mutation)
app = FastAPI()
app.include_router(GraphQLRouter(schema), prefix='/graphql')
